-- Generated by generate_sql.py --jeweler from jeweler.csv, gems.csv and gem_drops.csv.
-- All combine tiers unlocked; no jewelry, training or legendary gems.
DROP TABLE IF EXISTS `dc_jeweler_recipe`;
CREATE TABLE `dc_jeweler_recipe` (output_entry INT PRIMARY KEY,input_entry INT NOT NULL,input_count INT NOT NULL,gold_d3 INT NOT NULL,deaths_breath INT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
DROP TABLE IF EXISTS `dc_gem_drop`;
CREATE TABLE `dc_gem_drop` (min_level INT NOT NULL,max_level INT NOT NULL,min_tier INT NOT NULL,gem_tier VARCHAR(40) NOT NULL,PRIMARY KEY(min_level,min_tier)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
